function m1cRead(box, names) { const o = {}; names.forEach(n => { o[n] = +$("." + n, box).value; const b = $(".v" + n, box); if (b) b.textContent = m1cN(o[n]); }); return o; }
const m1cFr = (p, q) => texFrac(p, q);
const m1cP = x => x < 0 ? `(${x})` : `${x}`;
/* γραμμικός όρος ax + b σε LaTeX */
