      const W = 560, H = 300, cA = [215, 150], cB = [345, 150], r = 112;
      const svg = svgEl("svg", { viewBox: `0 0 ${W} ${H}`, class: "plot" }); $(".pl", box).innerHTML = ""; $(".pl", box).appendChild(svg);
      const reg = n => { const a = A[1](n), b = B[1](n); return a && b ? "ab" : a ? "a" : b ? "b" : "o"; };
      const inRes = n => { const a = A[1](n), b = B[1](n); return op === "u" ? a || b : op === "i" ? a && b : op === "d" ? a && !b : b && !a; };
      const defs = svgEl("defs", {}); svg.appendChild(defs);
      const cp = (id, c) => { const p = svgEl("clipPath", { id }); p.appendChild(svgEl("circle", { cx: c[0], cy: c[1], r })); defs.appendChild(p); };
      const uid = "v" + Math.random().toString(36).slice(2, 7); cp(uid + "A", cA); cp(uid + "B", cB);
      svg.appendChild(svgEl("rect", { x: 8, y: 8, width: W - 16, height: H - 16, rx: 14, style: "fill:#fbfcff;stroke:#c9d4e6;stroke-width:1.5" }));
      const fillCol = "rgba(15,111,209,.28)";
