      const k = a.length, m = b.length;
      const num = BigInt(a + b) - BigInt(a || "0"), den = (10n ** BigInt(k)) * (10n ** BigInt(m) - 1n);
      let N = BigInt(I) * den + (I < 0 ? -num : num), D = den; const g = (x, y) => { x = x < 0n ? -x : x; while (y) [x, y] = [y, x % y]; return x; }; const gg = g(N, D); N /= gg; D /= gg;
