      const [a, b] = c.x, [lo, hi] = c.y; const P = makePlot($(".pl", box), { xmin: a, xmax: b, ymin: lo, ymax: hi, H: 300, xstep: niceStep(b - a), ystep: niceStep(hi - lo) });
      // πεδίο ορισμού: πράσινη ζώνη στον x· πεδίο τιμών: πορτοκαλί στον y
