      for (let i = 0; i <= N; i++) { const x = a + (b - a) * i / N; if (ok(x)) { if (st === null) st = x; } else if (st !== null) { m1cBand(P, st, x - (b - a) / N, lo + (hi - lo) * 0.03, m1cG, 7); st = null; } }
